 wedding:{n:'Wedding',s:'Groom, family & guests',c:'#8E1B2E',d:'Dress up properly: rich fabrics, full-length kurtas or sherwanis, and polished shoes. Day weddings suit lighter silks and pastels; evening weddings take jewel tones, velvet and brocade.',w:'Sherwanis for the groom, bandhgalas, Nehru jackets over silk kurtas, angrakhas, sharp suits for the reception.',a:'Outshining the groom (no safa or heavy sherwani as a guest), all-black or all-white at many Hindu weddings (check with the hosts), sneakers and denim.',t:'Ivory, gold, maroon, emerald, navy, rose.'},
 sangeet:{n:'Sangeet',s:'Music & dance night',c:'#5B2A86',d:'You will dance, so pick something with a little shine that you can move in. This is the night for Indo-western jackets and bolder colours.',w:'Indo-western long jackets, black or jewel-tone kurtas with stoles, printed Nehru jackets, dhoti-pant sets.',a:'Stiff heavy sherwanis, tight trousers you can’t dance in, and hard new shoes.',t:'Black, purple, teal, wine, metallic accents.'},
 mehendi:{n:'Mehendi',s:'Henna afternoon',c:'#2E7D32',d:'Relaxed, bright and comfortable. Expect to sit on the floor and get a little colour on you.',w:'Mint, green or printed cotton kurtas, short kurtas with churidar, printed shirts over dhoti pants.',a:'White or ivory that stains easily, heavy silk and formal suits.',t:'Mint, leaf green, mustard, peach, floral prints.'},
 haldi:{n:'Haldi',s:'Turmeric ceremony',c:'#D99A00',d:'You will get turmeric on you. Wear washable cotton or linen you don’t mind ruining.',w:'Yellow cotton kurtas with white pyjamas or dhotis, simple kurta sets, kolhapuris.',a:'Silk, anything dry-clean only, and good leather shoes.',t:'Turmeric yellow, marigold, mustard, white.'},
 festive:{n:'Festivals',s:'Diwali, Eid, Navratri, Onam, Puja',c:'#C2410C',d:'Traditional with a sense of occasion. Onam means kasavu mundu, Eid suits a crisp pathani or kurta, Navratri calls for mirror-work and colour, Diwali for silk.',w:'Silk kurta sets, Nehru jackets, pathani suits, mundu with shirt, mirror-work kurtas for garba.',a:'Synthetic fabric near diyas and fireworks, and dull everyday clothes.',t:'Gold, maroon, saffron, green, ivory.'},
 pooja:{n:'Pooja & Temple',s:'Prayers & ceremonies',c:'#9A3412',d:'Simple, modest and clean. You may sit on the floor and remove your shoes, so pick comfort and easy footwear.',w:'Cotton or chikan kurta pyjamas, dhotis, mundu or veshti with a shirt, khadi kurtas.',a:'Leather belts and bags at many temples, shorts, loud graphic tees.',t:'White, ivory, saffron, sandalwood, yellow.'},
 office:{n:'Office',s:'Everyday work',c:'#1E3A5F',d:'Clean, comfortable and repeatable. Well-fitted basics in solid colours beat anything trendy.',w:'Oxford shirts, chinos and tailored trousers, polos on casual days, Nehru jackets, short kurtas with trousers.',a:'Wrinkled shirts, loud prints, gym wear and worn-out shoes.',t:'Navy, white, light blue, grey, olive, beige.'},
 interview:{n:'Interview',s:'First impressions',c:'#1F2937',d:'Look one notch smarter than the people who work there. Fit, ironing and clean shoes matter more than price.',w:'Navy or charcoal suits for corporate roles, blazer with chinos for startups and creative roles, plain white or light blue shirts.',a:'Loud ties, strong fragrance, sneakers (unless you know the culture), and anything that needs adjusting.',t:'Navy, charcoal, white, light blue, burgundy accents.'},
 date:{n:'Date Night',s:'Dinner & drinks',c:'#9F1239',d:'Look like you made an effort without looking stiff. One good layer and great shoes do most of the work.',w:'Dark jeans with a blazer or leather jacket, knit polos, henleys, turtlenecks under a coat.',a:'Office shirt and tie, heavy cologne, scuffed sneakers.',t:'Black, burgundy, navy, camel, olive.'},
 brunch:{n:'Brunch & Day Out',s:'Weekend daytime',c:'#B45309',d:'Light, easy and a little colourful. Daytime is when you can wear pastels, linen and soft prints.',w:'Polos and chinos, gingham shirts, linen shirts, short kurtas with jeans, clean white sneakers or loafers.',a:'Full suits, heavy dark fabrics, and gym wear.',t:'Pastels, white, beige, sage, light blue.'},
 party:{n:'Party & Night Out',s:'Clubs, birthdays & parties',c:'#4C1D95',d:'Darker colours, sharper fits and one statement piece: a jacket, a printed shirt or great boots.',w:'Leather or bomber jackets, black jeans, printed shirts, bandhgala jackets over tees, Chelsea boots.',a:'Office trousers and shirts, baggy fits, and formal lace-ups with jeans.',t:'Black, deep blue, burgundy, metallic accents.'},
 cocktail:{n:'Cocktail & Reception',s:'Evening events',c:'#7C2D12',d:'Somewhere between a suit and a party outfit. Dark suits without a tie, velvet, or a sharp bandhgala all work.',w:'Dark suits with an open collar, bandhgalas, Indo-western jackets, tuxedos for black-tie receptions.',a:'Daytime pastels, casual denim and backpacks.',t:'Midnight blue, black, emerald, wine.'},
 formal:{n:'Formal & Black Tie',s:'Galas, awards & formal dinners',c:'#111827',d:'Follow the dress code. Black tie means a tuxedo or a dark bandhgala; formal means a dark suit and tie.',w:'Tuxedos, dark suits, black or midnight bandhgalas, patent or polished oxfords.',a:'Brown shoes with black tie, novelty socks, loose ties.',t:'Black, midnight blue, charcoal, white.'},
 travel:{n:'Travel',s:'Flights, road trips & holidays',c:'#0F766E',d:'Comfortable layers that still look put together, and shoes you can walk in all day.',w:'Hoodies or knits with joggers, tee and jeans with an overshirt, trench or field jacket, clean sneakers.',a:'Stiff formal shoes, too many items, and fabrics that crease badly.',t:'Navy, olive, grey, black, khaki.'},
 college:{n:'College & Everyday',s:'Campus & daily wear',c:'#2563EB',d:'Comfortable, affordable and easy to repeat. Good basics and one or two jackets go a long way.',w:'Tees and jeans, denim or bomber jackets, hoodies, short kurtas with jeans, white sneakers.',a:'Overdressing for class, worn-out graphic tees, and flip-flops in labs.',t:'Denim blue, white, black, olive, grey.'},
 beach:{n:'Beach & Vacation',s:'Sun, sand & resort',c:'#0284C7',d:'Breathable linen and cotton, lighter colours and relaxed fits. Pack sunglasses and real sandals.',w:'Linen shirts with shorts, tropical prints, linen kurtas, chino shorts, espadrilles or sandals.',a:'Dark heavy fabrics, skinny jeans, and socks with sandals.',t:'White, sky blue, sand, coral, sea green.'}
